/* From Uiverse.io by Praashoo7 - Tags: neumorphism, red, realistic, radio, cross */
.__UIV_SCOPE__ .radio-input {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .radio-input input {
  appearance: none;
  width: 2em;
  height: 2em;
  background-color: #171717;
  box-shadow: inset 2px 5px 10px rgb(5, 5, 5);
  border-radius: 5px;
  transition: .4s ease-in-out;
}

.__UIV_SCOPE__ .radio-input input:hover {
  scale: 1.2;
  cursor: pointer;
  box-shadow: none;
}

.__UIV_SCOPE__ .radio-input .plus1 {
  position: relative;
  top: 0.01em;
  left: -1.45em;
  width: 1.3em;
  height: 0.2em;
  background-color: red;
  rotate: 45deg;
  scale: 0;
  border-radius: 5px;
  transition: .4s ease-in-out;
}

.__UIV_SCOPE__ .radio-input .plus2 {
  position: relative;
  width: 1.3em;
  height: 0.2em;
  background-color: red;
  transform: rotate(90deg);
  border-radius: 5px;
  transition: .4s ease-in-out;
}

.__UIV_SCOPE__ .radio-input input:checked {
  box-shadow: none;
}

.__UIV_SCOPE__ .radio-input input:checked + .plus1 {
  transform: rotate(180deg);
  scale: 1;
}
